					{ title: '知产服务', sub: '商标专利版权一站搞定', bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }
				],
				menus: [
					{ title: '工商服务', icon: 'auth-filled', bg: '#2979ff' },
					{ title: '代理记账', icon: 'wallet-filled', bg: '#2ECC71' },
					{ title: '企业转让', icon: 'loop', bg: '#FF6B6B' },
					{ title: '注册商标', icon: 'flag-filled', bg: '#F39C12' },
					{ title: '专利申请', icon: 'paperplane-filled', bg: '#9B59B6' },
					{ title: '版权登记', icon: 'images-filled', bg: '#1ABC9C' },
					{ title: '税务查询', icon: 'search', bg: '#E74C3C' },
					{ title: '查看全部', icon: 'list', bg: '#34495E' }
				],
				adBg: 'linear-gradient(120deg, #FF6B6B 0%, #FFA07A 55%, #F39C12 100%)',
				regBg: 'linear-gradient(135deg, #2979ff 0%, #192a56 100%)',
				bookBg: 'linear-gradient(135deg, #2ECC71 0%, #10ac84 100%)',
				packages: [
					{
						name: '标准套餐',
						price: '2999',
						tag: '入门创业',
						features: ['公司注册', '代理记账1年', '印章一套']
					},
					{
						name: '高级套餐',
						price: '5999',
						tag: '推荐',
						features: ['公司注册', '代理记账2年', '印章一套', '商标注册']
					}
				],
				ipTags: ['商标注册', '专利申请', '版权登记']
			}
		},
		onShareAppMessage() {
			return {
				title: '企业服务 - 超级供应链',
				path: '/pages/tabBar/service/service'
			}
		},
		onShow() {
			// 1) layoutTick 自增 + key 变化 → Vue 丢弃旧 DOM 重建 menu-card
			this.layoutTick = (this.layoutTick + 1) & 0xffff
			// 2) 等 DOM 挂载后，强制读取 menu-card 实际尺寸触发 reflow
			//    彻底杜绝 keep-alive 激活后保留的 layout 缓存把两行并成一行
			this.$nextTick(() => {
				try {
					const q = uni.createSelectorQuery().in(this)
					q.select('.menu-card').boundingClientRect()
					q.selectAll('.menu-card > view').boundingClientRect()
					q.exec(() => { /* 仅触发重排，不需要处理结果 */ })
				} catch (e) {}
				// 兜底：一帧后再触发一次（兼容 activated 延迟挂载）
				setTimeout(() => {
					try {
						const q2 = uni.createSelectorQuery().in(this)
						q2.select('.menu-card').boundingClientRect()
						q2.exec(() => {})
					} catch (e) {}
				}, 60)
			})
		},
		methods: {
			onBanner(b) { uni.showToast({ title: b.title, icon: 'none' }) },
			onMenu(m) {
				// 「查看全部」仍是占位，其余菜单跳服务详情页
				if (m.title === '查看全部') {
					uni.showToast({ title: '查看全部服务', icon: 'none' })
					return
				}
				uni.navigateTo({
					url: '/pages/product/detail?title=' + encodeURIComponent(m.title)
				})
			},
			onSolution() { uni.showToast({ title: '一站式企业服务方案', icon: 'none' }) },
			onAd() { uni.showToast({ title: '广告优惠', icon: 'none' }) },
			onImgItem(t) { uni.showToast({ title: t, icon: 'none' }) },
			onPackage(p) { uni.showToast({ title: p.name, icon: 'none' }) },
			onMixItem(t) { uni.showToast({ title: t, icon: 'none' }) },
			onViewAll() { uni.showToast({ title: '查看所有服务', icon: 'none' }) }
		}
	}
</script>

